        { "number": 2, "question": "(2) A. had to | B. start | C. have to | D. began", "options": ["A", "B", "C", "D"], "answer": "A", "explanation": "Sự việc xảy ra ở quá khứ 'last year' -> dùng dạng quá khứ 'had to'." },
        { "number": 3, "question": "(3) A. stereo | B. radio | C. television | D. the Internet", "options": ["A", "B", "C", "D"], "answer": "D", "explanation": "Tìm kiếm thông tin trên mạng dùng cụm 'searched the Internet'." },
        { "number": 4, "question": "(4) A. about | B. with | C. on | D. at", "options": ["A", "B", "C", "D"], "answer": "B", "explanation": "Cấu trúc tính từ: 'happy with something' (vui mừng/hài lòng với món quà)." },
        { "number": 5, "question": "(5) A. more | B. many | C. the most | D. some", "options": ["A", "B", "C", "D"], "answer": "A", "explanation": "Cấu trúc so sánh hơn với tính từ dài 'more careful and patient'." }
