        { "number": 6, "question": "They / interested / play / badminton / after school ?", "answer": "Are they interested in playing badminton after school?", "explanation": "Câu hỏi Yes/No: Are they interested in + V-ing...?" },
        { "number": 7, "question": "I / not fond / make models / because / I / not patient.", "answer": "I am not fond of making models because I am not patient. / I'm not fond of making models because I'm not patient.", "explanation": "Cấu trúc: I am not fond of + V-ing..." },
        { "number": 8, "question": "Why / you / not interested / cook ? because / I / often / burn myself", "answer": "Why are you not interested in cooking? Because I often burn myself.", "explanation": "Câu hỏi: Why are you not interested in + V-ing?" },
        { "number": 9, "question": "My friends / keen / do judo / and / they / go / judo club / every Sunday.", "answer": "My friends are keen on doing judo and they go to the judo club every Sunday.", "explanation": "Cấu trúc: are keen on doing judo... go to the judo club." },
        { "number": 10, "question": "Their children / be / afraid of / walk / on the street / night.", "answer": "Their children are afraid of walking on the street at night.", "explanation": "Cấu trúc: be afraid of + V-ing (sợ làm gì) và giới từ chỉ thời gian 'at night'." }
